from revisar_guia94 import *
edit(source(22),[('conforme essas regras','de acordo com essas regras'),('Ela não cura, não acorda, não reduz o requisito e conserva o tratamento acumulado e as rodadas restantes.','Estabilizar não cura nem acorda a pessoa. O tratamento necessário, o total acumulado e as rodadas restantes permanecem.'),('[piloto comentado]','[exemplo comentado]')],'Segundo pente-fino, páginas 73–76')
edit(source(23),[('confira a limite de carga','confira o limite de carga')],'Segundo pente-fino, página 77: concordância')
edit(source(56),[('**Comece por aqui para preparar uma ameaça ou um confronto.** Siga os passos abaixo para começar.','**Para criar um inimigo ou preparar um confronto, siga os passos abaixo.**'),('[ficha única de construção e encontro]','[ficha de inimigo e encontro]'),('**Regra do Livro de Regras 1.0** é uma regra publicada: ações, fórmulas, requisitos e limites continuam valendo. **Orientação do Guia** ensina a preparar e conduzir; por exemplo, comparar uma alteração de cada vez. **Proposta experimental** é um número ou uma habilidade que o Guia está desenvolvendo. **Escolha desta missão** define mapa, prioridades ou desfechos dentro das permissões existentes.','**Regras do jogo.** As ações, fórmulas, requisitos e limites do Livro de Regras 1.0 continuam valendo. **Dicas do Guia** ajudam a preparar e conduzir o jogo, como comparar uma alteração de cada vez. **Propostas experimentais** são números ou habilidades em avaliação. **Escolhas da missão** definem mapa, prioridades e desfechos possíveis, respeitando as regras.')],'Segundo pente-fino, páginas 82–85')
edit(source(59),[('Os exemplos de alteração são experimentais; o Livro de Regras 1.0 e as fichas do piloto conservam suas regras. As comparações completas estão no [registro 64](<../04 - Planejamento/64-prototipos-de-recursos-dos-inimigos.md>).','As alterações sugeridas aqui são experimentais. Elas não mudam as regras nem as fichas apresentadas no exemplo de missão.'),('A [comparação completa](<../04 - Planejamento/64-prototipos-de-recursos-dos-inimigos.md>) define início, prazo, interrupção e preço experimental; este parágrafo não substitui aquela ficha.','Este exemplo apresenta a ideia. Antes de usá-la, complete a ficha com início, prazo, interrupção e custo, conforme [Montar as habilidades de um inimigo](60-construir-capacidades-de-inimigos.md).')],'Segundo pente-fino, páginas 86–88: retirar remissão de bastidores sem destino no livro')
for p in (R/'06 - Redacao do Guia').glob('*.md'):
 pairs=[(a,b) for a,b in [('[Régua inicial de números]','[Escolher os números de um inimigo]'),('[Recursos e ritmo]','[PE, recarga e limites de uso]')] if a in p.read_text()]
 if pairs:edit(str(p.relative_to(R)),pairs,'Segundo pente-fino: nome de seção nas remissões')
